/**
 * Experiment harness: runs the generator under test over the fixture
 * through the REAL SKMTC pipeline (parse → generate → render), writes the
 * artifacts to ./out/, and saves capture.json ({artifacts, inspection})
 * plus manifest.json for scoring and inspection tooling.
 *
 * Invoked via `deno task generate` / `deno task verify`. Not part of the
 * task deliverable — do not edit.
 */
import { StackTrail, toArtifacts } from '@skmtc/core'
import type { SkmtcDocumentInput } from '@skmtc/core'
import { dirname, fromFileUrl } from '@std/path'
import entry from './gen-kotlin-jackson/mod.ts'

const here = dirname(fromFileUrl(import.meta.url))

const raw: unknown = JSON.parse(await Deno.readTextFile(`${here}/fixture/openapi.json`))

// Test-infra cast: the fixture is authored as a valid OpenAPI 3.0 document.
const document = { type: 'oas', value: raw } as SkmtcDocumentInput

const toGeneratorConfigMap = (() => ({ [entry.id]: entry })) as Parameters<
  typeof toArtifacts
>[0]['toGeneratorConfigMap']

const result = toArtifacts({
  traceId: 'exp',
  spanId: 'exp',
  document,
  settings: undefined,
  toGeneratorConfigMap,
  stackTrail: StackTrail.empty(),
  startAt: Date.now(),
  silent: true,
  inspect: true
})

const outRoot = `${here}/out`
await Deno.remove(outRoot, { recursive: true }).catch(() => {})

const written: string[] = []
for (const [key, content] of Object.entries(result.artifacts)) {
  const rel = key.replace(/^@\/?/, '')
  const path = `${outRoot}/${rel}`
  await Deno.mkdir(dirname(path), { recursive: true })
  await Deno.writeTextFile(path, content)
  written.push(rel)
}

await Deno.writeTextFile(
  `${here}/capture.json`,
  JSON.stringify({ artifacts: result.artifacts, inspection: result.inspection ?? null }, null, 2)
)
await Deno.writeTextFile(`${here}/manifest.json`, JSON.stringify(result.manifest, null, 2))

// manifest.results is a nested tree (phase → generator → subject → variant)
// whose leaves are status strings — count the leaves.
const resultCounts: Record<string, number> = {}
const countLeaves = (node: unknown): void => {
  if (typeof node === 'string') {
    resultCounts[node] = (resultCounts[node] ?? 0) + 1
    return
  }
  if (node !== null && typeof node === 'object') {
    Object.values(node).forEach(countLeaves)
  }
}
countLeaves(result.manifest.results ?? {})
const parseIssues = result.manifest.parseIssues ?? []

console.log(`artifacts written to out/: ${written.length}`)
for (const rel of written.sort()) console.log(`  ${rel}`)
console.log(`results: ${JSON.stringify(resultCounts)}`)
console.log(`parseIssues: ${Array.isArray(parseIssues) ? parseIssues.length : 'n/a'}`)

if (written.length === 0) {
  console.error('FAIL: the run produced zero artifacts')
  Deno.exit(1)
}
if (resultCounts['error']) {
  console.error(`FAIL: ${resultCounts['error']} subject(s) errored — see manifest.json`)
  Deno.exit(1)
}

#!/usr/bin/env node
// Structural verification of the generated Kotlin (no kotlinc on this
// machine). Part of `deno task verify` — do not edit. Exits non-zero on
// any failure.
import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

const outDir = 'out/com/example/models'
const failures = []
const ok = (cond, msg) => {
  if (!cond) failures.push(msg)
}

const models = ['Order', 'OrderItem', 'OrderStatus', 'Address', 'Category']
const files = {}
for (const model of models) {
  const path = join(outDir, `${model}.generated.kt`)
  ok(existsSync(path), `missing file: ${path}`)
  if (existsSync(path)) files[model] = readFileSync(path, 'utf8')
}

for (const [model, text] of Object.entries(files)) {
  ok(/^package com\.example\.models$/m.test(text), `${model}: missing 'package com.example.models' directive`)
  ok(!text.includes('??'), `${model}: doubled '?' in a type`)
  ok(!/^import com\.example\.models\./m.test(text), `${model}: same-package import should be suppressed`)
}

const order = files['Order'] ?? ''
ok(/data class Order\s*\(/.test(order), 'Order: not a data class')
ok(order.includes('@JsonProperty("shipping_address")'), 'Order: missing @JsonProperty("shipping_address")')
ok(/val shippingAddress: Address\b/.test(order), 'Order: shippingAddress not typed Address')
ok(/val billingAddress: Address\? = null/.test(order), 'Order: billingAddress should be `Address? = null` (optional)')
ok(/val customerNotes: String\? = null/.test(order), 'Order: customerNotes should be `String? = null` (nullable+optional)')
ok(/val `object`: String\b/.test(order), 'Order: hard keyword must be backticked `object`')
ok(!order.includes('@JsonProperty("object")'), 'Order: `object` keeps its wire name — no @JsonProperty needed')
ok(/val items: List<OrderItem>\b/.test(order), 'Order: items not typed List<OrderItem>')
ok(/^import com\.fasterxml\.jackson\.annotation\.JsonProperty$/m.test(order), 'Order: missing Jackson JsonProperty import')

const item = files['OrderItem'] ?? ''
ok(item.includes('@JsonProperty("unit_price")'), 'OrderItem: missing @JsonProperty("unit_price")')
ok(/val unitPrice: /.test(item), 'OrderItem: unit_price not renamed to unitPrice')
ok(/val giftWrap: \w+\? = null/.test(item), 'OrderItem: gift_wrap should be optional with default null')

const status = files['OrderStatus'] ?? ''
ok(/enum class OrderStatus/.test(status), 'OrderStatus: not an enum class')
for (const value of ['pending', 'paid', 'shipped', 'cancelled']) {
  ok(status.toLowerCase().includes(value), `OrderStatus: wire value '${value}' unrepresented`)
}

const category = files['Category'] ?? ''
ok(/val children: List<Category>\? = null/.test(category), 'Category: children should be `List<Category>? = null` (self-reference)')

if (failures.length) {
  console.error(`KOTLIN CHECKS FAILED (${failures.length}):`)
  for (const f of failures) console.error(`  - ${f}`)
  process.exit(1)
}
console.log(`kotlin checks: all pass (${models.length} files)`)

