=== KtDefinition ===
import { DefinitionBase } from 'jsr:@skmtc/core@0.28.3'
import type { GeneratedValue, GenerateContextType } from 'jsr:@skmtc/core@0.28.3'
import { toKtAnnotations } from './KtAnnotation.ts'
import { isKtDocumented } from './KtDocumented.ts'
import type { KtIdentifier } from './KtIdentifier.ts'
import { withDescription } from './withDescription.ts'

/**
 * Constructor arguments for {@link KtDefinition}.
 */
export type KtDefinitionArgs<Value extends GeneratedValue> = {
  context: GenerateContextType
  identifier: KtIdentifier
  value: Value
  description?: string
}

/**
 * Kotlin's concrete {@link DefinitionBase}: renders the identifier's
 * declaration head and the value, each rendering itself.
 *
 * - **Assignment kinds** (`typealias`, `val`) — `${head} = ${value}`;
 *   the value is the right-hand-side expression.
 * - **Declaration kinds** (`class`, `data-class`, `enum-class`,
 *   `interface`, `sealed-interface`) — `${head}${value}`; the value
 *   renders everything after the head: a
 *   {@link import('./KtParameterList.ts').KtParameterList} (parentheses
 *   included), a
 *   {@link import('./KtPrimaryConstructor.ts').KtPrimaryConstructor}
 *   (modifiers + the explicit `constructor` keyword), plus inline
 *   ` : A, B` supertype clauses and ` {\n…\n}` braced bodies — plain
 *   Kotlin syntax carries no grammar rule worth a class. A value that
 *   renders nothing yields the bodyless idiom (`sealed interface
 *   Animal`, `class Marker`) — the value decides its own form; the
 *   definition never inspects it.
 * (Raw whole-file content — static template files — is a FILE fact, not
 * a definition: it flows through the register vocabulary's `custom`
 * field onto `FileBase.custom`, with no identifier involved.)
 *
 * Two protocols remain on the value because they render OUTSIDE the
 * head+value line: class-level annotations
 * ({@link import('./KtAnnotation.ts').KtAnnotated}, one per line above
 * the declaration — the neutral `Lang.toDefinition` signature has no
 * annotations slot) and KDoc
 * ({@link import('./KtDocumented.ts').KtDocumented}, above the
 * annotations; an explicit constructor `description` wins).
 *
 * (A foreign identifier is refused earlier, at the `Lang.toDefinition`
 * boundary in `KtLang`; the constructor only accepts a
 * {@link KtIdentifier}.)
 *
 * Visibility is the identifier's fact, rendered in its head (`private
 * data class …` — see {@link KtIdentifier.toString}). The neutral
 * `noExport` flag the Drivers pass is folded into a restricted identifier
 * copy at the `KtLang.toDefinition` boundary, so this class never sees
 * it.
 */
export class KtDefinition<
  Value extends GeneratedValue = GeneratedValue
> extends DefinitionBase<Value> {
  /** Narrows the inherited neutral `identifier` to the concrete Kotlin
   *  subclass (the constructor only accepts a {@link KtIdentifier}). */
  declare identifier: KtIdentifier

  description: string | undefined

  constructor({ context, identifier, value, description }: KtDefinitionArgs<Value>) {
    super({ context, identifier, value })

    this.description = description
  }

  override toString(): string {
    const declaration = `${toKtAnnotations(this.value)}${this.toShell()}`

    // Constructor description wins; else the value-carried protocol.
    const description =
      this.description ?? (isKtDocumented(this.value) ? this.value.description : undefined)

    return withDescription(declaration, { description })
  }

  private toShell(): string {
    switch (this.identifier.type) {
      case 'typealias':
      case 'val':
        // Assignment kinds: the value is the right-hand side.
        return `${this.identifier} = ${this.value}`
      default:
        // Declaration kinds: the identifier renders its head, the value
        // renders everything after it (constructor, supertypes, body).
        return `${this.identifier}${this.value}`
    }
  }
}
=== KtFile ===
import { CodeFileBase, matchDefinitions } from 'jsr:@skmtc/core@0.28.3'
import type { ClientSettings, DefinitionBase, ImportBase, ReExportBase } from 'jsr:@skmtc/core@0.28.3'
import { KtImport } from './KtImport.ts'
import { KtIdentifier } from './KtIdentifier.ts'
import type { KtEntityType } from './createIdentifier.ts'
import { toPackageName } from './toPackageName.ts'

/**
 * Constructor arguments for {@link KtFile} — the `Lang.createFile` shape.
 */
export type KtFileArgs = {
  path: string
  settings: ClientSettings | undefined
}

/**
 * Kotlin's concrete code file. Owns the definition + import collections and
 * their merge policy (the neutral {@link CodeFileBase} declares the
 * contract) and adds the Kotlin-specific pieces:
 *
 * - the `package` directive, DERIVED from the file's own path via
 *   {@link toPackageName} — the export path encodes the package
 *   (`@/com/example/api/User.generated.kt` → `package com.example.api`);
 *   `client.json#settings.basePath` points at the Gradle source root.
 * - **same-package import suppression**: any import whose resolved
 *   package equals this file's package is omitted at render (same-package
 *   symbols need no import in Kotlin — the structural analog of TsFile's
 *   intra-package `@/` normalization). In particular the Driver's
 *   cross-file peer imports vanish when peers share the package.
 * - the rendering arrangement: the neutral `custom` slot
 *   ({@link FileBase.custom}) first — leading content above the
 *   `package` directive (e.g. a generated-file attribution banner;
 *   only comments may precede `package`), the same placement `TsFile`
 *   gives it — then the package directive, imports (one statement
 *   per symbol, **sorted alphabetically** — not style, which is the
 *   consumer's formatter's job, but registration-order independence:
 *   the rendered bytes are what snapshot tests and byte-identical
 *   regression gates compare), then definitions joined by blank lines.
 *
 * `reExports` cannot arrive by construction — Kotlin's concise register
 * vocabulary has no `reExports` field and the Driver never registers
 * them — so rendering ignores the (always empty) neutral map.
 */
export class KtFile extends CodeFileBase {
  /**
   * The `package` this file declares — derived from `path`, with the
   * owning package's `rootPath` stripped first in multi-package mode
   * (`settings.packages`).
   */
  packageName: string
  /** Threaded into package derivation and same-package suppression. */
  settings: ClientSettings | undefined

  /** Definitions keyed by identifier name (first write wins; Kotlin has no declaration merging). */
  definitions: Map<string, DefinitionBase> = new Map()

  /** Imports keyed by {@link ImportBase.mergeKey}. */
  imports: Map<string, ImportBase> = new Map()

  /** Re-exports keyed by {@link ReExportBase.mergeKey} — Kotlin registers none; kept for the neutral contract. */
  reExports: Map<string, ReExportBase> = new Map()

  constructor({ path, settings }: KtFileArgs) {
    super({ path })
    this.packageName = toPackageName(path, settings?.packages)
    this.settings = settings
  }

  override addDefinition(definition: DefinitionBase): void {
    if (!this.definitions.has(definition.identifier.name)) {
      this.definitions.set(definition.identifier.name, definition)
    }
  }

  override addImports(incoming: ImportBase[]): void {
    for (const importEntry of incoming) {
      const key = importEntry.mergeKey()
      const existing = this.imports.get(key)
      this.imports.set(key, existing ? existing.merge(importEntry) : importEntry)
    }
  }

  override addReExports(incoming: ReExportBase[]): void {
    for (const reExportEntry of incoming) {
      const key = reExportEntry.mergeKey()
      const existing = this.reExports.get(key)
      this.reExports.set(key, existing ? existing.merge(reExportEntry) : reExportEntry)
    }
  }

  override findDefinitions(query?: {
    name?: string
    type?: KtEntityType
  }): DefinitionBase[] | undefined {
    return matchDefinitions([...this.definitions.values()], query, identifier =>
      identifier instanceof KtIdentifier ? identifier.type : undefined
    )
  }

  override toString(): string {
    const packages = this.settings?.packages

    const importLines = Array.from(this.imports.values())
      .flatMap(importEntry => {
        if (!(importEntry instanceof KtImport)) {
          return [importEntry.toString()]
        }

        if (importEntry.resolvedPackage(packages) === this.packageName) {
          return []
        }

        return importEntry.toLines(packages)
      })
      .sort()

    const definitions = Array.from(this.definitions.values())
      .map(definition => definition.toString())
      .join('\n\n')

    const sections = [
      // The neutral leading-content slot (FileBase.custom) — e.g. a
      // generated-file attribution banner; only comments may precede
      // `package`. Set through the register vocabulary's `custom` field.
      this.custom === undefined ? '' : `${this.custom}`,
      this.packageName ? `package ${this.packageName}` : '',
      importLines.join('\n'),
      definitions
    ]

    return `${sections.filter(section => Boolean(section.length)).join('\n\n')}\n`
  }
}
=== register ===
import { normalize } from 'jsr:/@std/path@^1.0.9/normalize'
import invariant from 'npm:tiny-invariant@1.3.3'
import type { DefinitionBase, GenerateContextType, GeneratedValue, Stringable } from 'jsr:@skmtc/core@0.28.3'
import { KtFile } from './KtFile.ts'
import { KtImport, type KtImportNameArg } from './KtImport.ts'
import { KtDefinition } from './KtDefinition.ts'
import type { KtIdentifier } from './KtIdentifier.ts'

/**
 * Kotlin's concise register vocabulary — the generator-facing form.
 *
 * Owned by this package: each language defines its own concise args type
 * exposing only what the language supports. Kotlin has **no re-exports**,
 * so there is deliberately no `reExports` field — a generator trying to
 * register one is a compile-time error, not a runtime no-op (the note-16
 * Go example, realized).
 */
export type KtRegisterArgs = {
  /**
   * Import statements to include, keyed by module: a dotted package
   * (`'kotlinx.serialization'`) for external libraries, or an `@/`-export
   * path for project files.
   */
  imports?: Record<string, KtImportNameArg[]>
  /** Definition objects to include in the destination file. */
  definitions?: (DefinitionBase | undefined)[]
  /**
   * Leading file content, set on the destination file's neutral
   * `custom` slot ({@link FileBase.custom}) and rendered by
   * {@link KtFile} ABOVE the `package` directive — e.g. a
   * generated-file attribution banner (only comments may precede
   * `package`). The same placement `TsFile` gives the slot; the same
   * neutral semantics too — last non-`undefined` write wins.
   */
  custom?: Stringable
}

/**
 * Kotlin's register function — the single implementation behind
 * {@link KtSnippet.register} and the projection-base veneers.
 *
 * Converts the concise import form into {@link KtImport} objects, creates
 * the destination {@link KtFile} on first write (caller-side creation —
 * the language is right here), and hands pure data to the neutral
 * `context.register`. No `generatorId`, no `Lang` object: the language is
 * this module. Throws when the destination file exists but was created by
 * another language — a cross-language collision is a misconfiguration,
 * refused loudly rather than mixing Kotlin content into a foreign file.
 */
export const register = (
  context: GenerateContextType,
  args: KtRegisterArgs & { destinationPath: string }
): void => {
  const destinationPath = normalize(args.destinationPath)

  const file =
    context.getFile(destinationPath) ??
    context.addFile(new KtFile({ path: destinationPath, settings: context.settings }))

  invariant(
    file instanceof KtFile,
    `Cannot register Kotlin content into '${destinationPath}' — the file was created by another language`
  )

  context.register({
    imports: Object.entries(args.imports ?? {}).map(([module, names]) =>
      KtImport.fromConcise(module, names)
    ),
    definitions: args.definitions,
    custom: args.custom,
    destinationPath
  })
}

/**
 * Arguments for {@link defineAndRegister}.
 */
export type KtDefineAndRegisterArgs<Value extends GeneratedValue> = {
  identifier: KtIdentifier
  value: Value
  destinationPath: string
  /**
   * KDoc description rendered above the declaration — wins over the
   * value-carried {@link import('./KtDocumented.ts').KtDocumented}
   * protocol, exactly as on {@link KtDefinition}'s constructor.
   *
   * There is deliberately no `noExport` here: visibility is the
   * identifier's fact — pass `exported: false` to the identifier factory
   * (`createDataClass(name, { exported: false })`) instead.
   */
  description?: string
}

/**
 * Build a {@link KtDefinition} from `value` and register it at
 * `destinationPath`. The transform-level counterpart of
 * `this.defineAndRegister` — a transform (a closure with no class) imports
 * this directly; the language comes from the import, like everything else.
 *
 * No cache check — callers wrap with `context.findDefinition` first where
 * dedup is wanted (the gen-msw accumulator pattern).
 */
export const defineAndRegister = <Value extends GeneratedValue>(
  context: GenerateContextType,
  { identifier, value, destinationPath, description }: KtDefineAndRegisterArgs<Value>
): KtDefinition<Value> => {
  const definition = new KtDefinition({ context, identifier, value, description })

  register(context, { definitions: [definition], destinationPath })

  return definition
}

